fn solve(n: i8, k: i8) -> Vec<i8> {
    // total count (n) is at least 1
    // selected count (k) is between 0 and n inclusive
    
    let unselected = n - k; // number of unselected items
    
    if k == 0 || k == n {
        // If selected count is zero or equals total count,
        // both min and max are 0.
        vec![0, 0]
    } else {
        // Otherwise,
        // x_min = 1
        // x_max = min(unselected, 2 * selected)
        let x_min = 1;
        let x_max = unselected.min(2 * k);
        vec![x_min, x_max]
    }
}